*/



	//----W-Craft WebSquare 변환 확인: include----//
include("../js/PopupCalendar.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/common.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/mgt.js");
scwin.vScrenID = 'ULDMGT80203.gfm';
scwin.onpageload = function() {
};
scwin.onpageunload = function() {
};
scwin.fn_code1_sync = function() {
    var url1 = "/tbmccdval.do?method=searchTbmcCdval&inputMessageId=tbmccdval&outputMessageId=tbmccdval&CD_ID=00185";
    MxDataSet_code1.DataID = encodeURI(url1);

	//----W-Craft WebSquare 변환 확인: reset----//
    MxDataSet_code1.reset();
    var url2 = "/tbmccdval.do?method=searchTbmcCdval&inputMessageId=tbmccdval&outputMessageId=tbmccdval&CD_ID=01344";
    MxDataSet_code2.DataID = encodeURI(url2);

	//----W-Craft WebSquare 변환 확인: reset----//
    MxDataSet_code2.reset();
};
scwin.fn_list_sync = function() {
    var url = "/sndrcvlog.do?method=searchSndRcvLog&inputMessageId=sndrcvlog&outputMessageId=sndrcvlog&DISCLS_TRNSM_RSLT_SNDRCV_DDTM=" + txb_date.Text + "%&SNDRCV_TP_CD=" + MxDataSet_code1.getCellData(MxCombo1.getSelectedIndex() + 1, "CD_VAL") + "&DISCLS_SNDRCV_REL_INST_CD=" + MxDataSet_code2.getCellData(MxCombo2.getSelectedIndex() + 1, "CD_VAL") + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    MxDataSet.DataID = encodeURI(url);

	//----W-Craft WebSquare 변환 확인: reset----//
    MxDataSet.reset();
    $c.cm.ShowWin(MxGrid_1);
};
scwin.MxDataSet_OnLoadCompleted = function(e) {
    textbox_1.value = "총 " + rowcount + "건";
    $c.cm.CloseWin(rowcount, MxGrid_1);
};
scwin.gform_onload = function() {
    MxDataSet_code1.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=tbmccdval";

	//----W-Craft WebSquare 변환 확인: reset----//
    MxDataSet_code1.reset();
    MxDataSet_code2.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=tbmccdval";

	//----W-Craft WebSquare 변환 확인: reset----//
    MxDataSet_code2.reset();
    MxDataSet.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=sndrcvlog";

	//----W-Craft WebSquare 변환 확인: reset----//
    MxDataSet.reset();
    scwin.fn_code1_sync();
    $c.cm.PanelToGroupBox_01(panel_1);
    //PanelToGroupBox_02(panel_2);

	//----W-Craft WebSquare 변환 확인: toDaySet----//
    toDaySet(txb_date);
};
scwin.btn_cal_onclick = function(e) {

	//----W-Craft WebSquare 변환 확인: popUpCalendar----//
    popUpCalendar(txb_date_bg, 'txb_date', 'yyyymmdd'); //alert('image_2.onclick');

};
scwin.btn_sys_search_onclick = function(e) {
    if (txb_date.Text != "") {
        scwin.fn_list_sync(); //alert();

    } else {
        alert("접수일자를 지정하십시요");
    }
};
scwin.btn_toExcel_onclick = function(e) {
    MxGrid_1.GridToExcel("금감원송수신로그", "", "8");
};
